'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const money=n=>Number(n).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), pct=n=>n.toLocaleString('pt-BR',{maximumFractionDigits:1})+'%', esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), round=n=>Math.round((n+Number.EPSILON)*100)/100;
const paths={marca:'M12 22a10 10 0 1 1 0-20 10 10 0 0 1 0 20 M7.5 12.5l3 3 6-6.5',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',link:'M10 13a5 5 0 0 0 7 0l3-3a5 5 0 0 0-7-7l-2 2 M14 11a5 5 0 0 0-7 0l-3 3a5 5 0 0 0 7 7l2-2',upload:'M12 16V3 M7 8l5-5 5 5 M4 15v6h16v-6',spark:'m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z',clock:'M12 8v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',file:'M14 2H5v20h14V7z M14 2v6h5 M8 12h8 M8 16h8',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6z M8 12l3 3 5-6',arrow:'M5 12h14 M14 7l5 5-5 5',sun:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',close:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',wallet:'M3 5h17v15H3z M15 10h6v5h-6z',chart:'M4 3v18h17 M8 16l4-6 4 3 5-8',alert:'m12 3 10 18H2z M12 9v5 M12 17h.01',menu:'M4 6h16 M4 12h16 M4 18h16',download:'M12 3v13 M7 11l5 5 5-5 M3 18v3h18v-3',moon:'M20 15A9 9 0 0 1 9 3a9 9 0 1 0 11 12'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const platforms={'Bling':{color:'#77d6a0',short:'B',role:'Origem fiscal · ERP'},'Mercado Livre':{color:'#f4d66d',short:'ML',role:'Marketplace'},'Shopee':{color:'#ff9274',short:'S',role:'Marketplace'},'Magalu':{color:'#6bb5ff',short:'M',role:'Marketplace'},'Mercado Pago':{color:'#69d4ed',short:'MP',role:'Conta de liquidação'}};
const logo=p=>`<span class="plogo" style="background:${platforms[p].color}16;color:${platforms[p].color}">${platforms[p].short}</span>`;
const KEY='concilia-v1-local';
function seed(){return {orders:[],receipts:[],ledger:[],crm:{},audit:[],imports:[],closures:{},theme:'dark',schemaVersion:2};}
function cleanDemonstration(input){
 const state=input&&Array.isArray(input.orders)&&Array.isArray(input.receipts)?input:seed();
 if(state.schemaVersion>=2)return state;
 const isDemo=x=>x.source==='Demonstração';
 const ids=new Set(state.orders.filter(isDemo).map(x=>x.id));
 const demoMonths=new Set(state.orders.filter(isDemo).map(x=>x.date.slice(0,7)));
 const removedOrders=state.orders.filter(isDemo).length,removedReceipts=state.receipts.filter(isDemo).length;
 state.orders=state.orders.filter(x=>!isDemo(x));
 state.receipts=state.receipts.filter(x=>!isDemo(x)).map(x=>({...x,linkedOrder:ids.has(x.linkedOrder)?null:x.linkedOrder}));
 state.closures=Object.fromEntries(Object.entries(state.closures||{}).filter(([m,c])=>!demoMonths.has(m)&&!(c.orders||[]).some(isDemo)));
 state.audit=(state.audit||[]).filter(x=>x.action!=='Ambiente demonstrativo iniciado'&&!x.action.includes('demonstrativa')&&![...ids].some(id=>x.detail?.includes(id)));
 state.imports=state.imports||[];state.schemaVersion=2;
 state.audit.unshift({time:new Date().toISOString(),action:'Base operacional preparada',detail:`Removidos ${removedOrders} pedidos e ${removedReceipts} liberações demonstrativas. Registros importados preservados; fechamentos que continham demonstração reabertos.`});
 return state;
}
let db;let loadFailure=false;try{db=JSON.parse(localStorage.getItem(KEY))}catch{loadFailure=true}db=cleanDemonstration(db);db.ledger=db.ledger||[];db.crm=db.crm||{};
let page='dashboard',month=new Date().toLocaleDateString('sv-SE').slice(0,7),filter='',statusFilter='',platformFilter='',pendingImport=null,focusBefore=null;
document.body.classList.toggle('light',db.theme==='light');
function save(){if(loadFailure)return false;try{localStorage.setItem(KEY,JSON.stringify(db));return true}catch{toast('O navegador não permitiu salvar. Exporte um backup antes de sair.');return false}}
function audit(action,detail){paymentIndex=null;db.audit.unshift({id:uid(),time:new Date().toISOString(),action,detail});save()}
function uid(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2)}
function toast(s){$('#toast').className='toastshow';$('#toast').textContent=s;clearTimeout(toast.timer);toast.timer=setTimeout(()=>{$('#toast').className='';$('#toast').textContent=''},4500)}
const scoped=()=>db.orders.filter(o=>o.date.startsWith(month));
const net=o=>round(o.gross-o.fee);
let paymentIndex=null;
const paid=o=>{if(!paymentIndex){paymentIndex=new Map();for(const r of db.receipts)if(r.linkedOrder)paymentIndex.set(r.linkedOrder,(paymentIndex.get(r.linkedOrder)||0)+r.amount)}return round(paymentIndex.get(o.id)||0)};
function status(o){let p=paid(o);return p>0?(Math.abs(p-net(o))<.01?'Conciliado':'Divergência'):(o.transit?'Em trânsito':'A receber')}
const badges={'Conciliado':'ok','Divergência':'bad','Em trânsito':'info','A receber':'warn','A conciliar':'warn'};
const badge=s=>`<span class="badge ${badges[s]||'info'}">${esc(s)}</span>`;
function stats(rows=scoped()){const sum=f=>round(rows.reduce((a,o)=>a+f(o),0));return {gross:sum(o=>o.gross),fees:sum(o=>o.fee),net:sum(net),received:sum(paid),reconciled:sum(o=>status(o)==='Conciliado'?net(o):0),open:sum(o=>status(o)!=='Em trânsito'?Math.max(0,net(o)-paid(o)):0),transit:sum(o=>status(o)==='Em trânsito'?net(o):0),diff:sum(o=>status(o)==='Divergência'?Math.abs(net(o)-paid(o)):0),count:rows.length,matched:rows.filter(o=>status(o)==='Conciliado').length}}
function navigate(p){page=p;filter='';statusFilter='';platformFilter='';document.body.classList.remove('menu');render();window.scrollTo(0,0)}
const navItems=[['dashboard','grid','Visão geral'],['reconcile','link','Central de conciliação'],['imports','upload','Importar relatórios'],['ai','spark','Assistente IA'],['pending','alert','Pendências'],['closing','shield','Fechamento do mês'],['reports','file','Relatórios'],['history','clock','Histórico e auditoria']];
const MODULOS=[
 {id:'conc',ic:'link',t:'Conciliação',sub:'Plataformas × ERP',itens:[['Rotina',['reconcile','pending','closing']],['Dados',['integracoes','imports']]],plataformas:true},
 {id:'fin',ic:'wallet',t:'Financeiro',sub:'Contas a pagar e caixa',itens:[['Pagar',['pagar','compras']],['Caixa',['fluxo']]]},
 {id:'res',ic:'book',t:'Resultado',sub:'DRE e contabilidade',itens:[['Resultado',['contabil','reports']],['Vendas',['produtos','estados','clientes']]]},
 {id:'prec',ic:'tag',t:'Preços',sub:'Tabela e simulador',itens:[['Preços',['precos']]]}];
const NAVFIXO=['dashboard','equipe','ai','history'];
let moduloAtual=(()=>{try{return localStorage.getItem('ecombalance_mod')||'conc'}catch{return 'conc'}})();
function moduloDe(p){if(platforms[p])return 'conc';const m=MODULOS.find(m=>m.itens.some(([,ids])=>ids.includes(p)));return m?.id}
function sideNav(){const pm=moduloDe(page);if(pm&&pm!==moduloAtual){moduloAtual=pm;try{localStorage.setItem('ecombalance_mod',pm)}catch{}}const M=MODULOS.find(m=>m.id===moduloAtual)||MODULOS[0];
 const item=id=>{const n=navItems.find(n=>n[0]===id);return n?`<button data-nav="${id}" class="${page===id?'active':''}">${icon(n[1])}${n[2]}${id==='ai'?'<span class="navbadge">IA</span>':''}${id==='equipe'&&window.Integrations?.state?.reqs?.length?`<span class="navbadge" style="background:#edc47b30;color:var(--gold)">${window.Integrations.state.reqs.length}</span>`:''}</button>`:''};
 const usados=new Set([...NAVFIXO,...MODULOS.flatMap(m=>m.itens.flatMap(([,ids])=>ids))]),soltos=navItems.map(n=>n[0]).filter(id=>!usados.has(id));
 return `<nav>${item('dashboard')}</nav><div class="modswitch">${MODULOS.map(m=>`<button data-mod="${m.id}" class="${m.id===M.id?'active':''}" title="${m.sub}">${icon(m.ic)}<span>${m.t}</span></button>`).join('')}</div><div class="modtitle">${M.t}<small>${M.sub}</small></div>${M.itens.map(([g,ids])=>`<div class="navlabel">${g}</div><nav>${ids.map(item).join('')}</nav>`).join('')}${M.id==='conc'&&soltos.length?`<nav>${soltos.map(item).join('')}</nav>`:''}${M.plataformas?`<div class="navlabel">Por plataforma</div><nav class="platnav">${Object.keys(platforms).map(p=>`<button data-nav="${p}" class="${page===p?'active':''}"><span style="width:18px;color:${platforms[p].color};font-weight:700;font-size:11px">${platforms[p].short}</span>${p}</button>`).join('')}</nav>`:''}<div class="navlabel">Geral</div><nav>${item('equipe')}${item('ai')}${item('history')}</nav>`}
function shell(){let current=navItems.find(n=>n[0]===page)?.[2]||page;$('#app').innerHTML=`<aside><div class="brand"><span class="mark">${icon('marca')}</span><div>Jarvis<small>CONCILIAÇÃO E RESULTADO</small></div></div>${sideNav()}<div class="asidebottom"><div class="row"><span class="avatar">GK</span><div>Sua operação<br><span style="font-size:10px">Armazenamento neste navegador</span></div></div></div></aside><main><header><div class="row"><button class="quiet mobilemenu" data-action="menu" aria-label="Abrir navegação">${icon('menu')}</button><span class="breadcrumb">${esc(MODULOS.find(m=>m.id===moduloDe(page))?.t||'Jarvis')} <span style="margin:0 10px">/</span> <strong>${esc(current)}</strong></span></div><div class="row"><span class="demo">BASE OPERACIONAL</span><button class="quiet small" data-action="theme" aria-label="Alternar modo claro e escuro">${icon(db.theme==='light'?'moon':'sun')}</button><span class="avatar">GK</span></div></header><div class="content"><div class="heading"><div><div class="eyebrow">${platforms[page]?'Ecossistema · visão individual':'Controle, clareza e confiança'}</div><h1>${page==='dashboard'?'Seu financeiro, em perspectiva.':esc(current)}</h1><p>${subtitle()}</p></div><div class="row"><select id="month" aria-label="Competência">${[...new Set([month,...db.orders.map(o=>o.date.slice(0,7)),...db.receipts.map(r=>r.date.slice(0,7))])].sort().reverse().map(m=>`<option value="${m}" ${month===m?'selected':''}>${new Date(m+'-15T12:00:00').toLocaleDateString('pt-BR',{month:'long',year:'numeric'})}</option>`).join('')}</select><button data-nav="imports" class="primary">${icon('upload')} Importar</button></div></div><div id="view"></div><div class="footer"><span>Jarvis / Dados salvos neste navegador · Sem conexão com contas externas</span><span><span class="dot"></span>Seu controle começa com clareza.</span></div></div></main>`;$('#month').onchange=e=>{month=e.target.value;render()}}
function subtitle(){return {dashboard:'Uma visão unificada da operação. Cada venda, cada repasse, cada detalhe.',reconcile:'Cruze pedidos, liberações e valores. Você confirma cada vínculo.',imports:'Transforme relatórios em uma visão única da sua operação.',ai:'Evidências e hipóteses para investigar o que ainda não fechou.',pending:'Acompanhe diferenças, liberações e vínculos em aberto.',closing:'Revise a competência e preserve um retrato do fechamento.',reports:'Dados rastreáveis para apoiar a revisão da contabilidade.',history:'Cada ação registrada. Cada decisão com contexto.'}[page]||platforms[page]?.role||''}
function render(){paymentIndex=null;shell();$('#view').innerHTML=page==='dashboard'?dashboard():page==='reconcile'?central():page==='imports'?importsView():page==='ai'?aiView():page==='pending'?pendingView():page==='closing'?closingView():page==='reports'?reportsView():page==='history'?historyView():platformView(page);bindFilters()}
function metric(label,value,caption,ic='wallet',tone=''){return `<div class="card metric"><div class="label">${label}${icon(ic)}</div><div class="value ${tone}">${money(value)}</div><small>${caption}</small></div>`}
function metrics(s){return `<div class="grid metrics">${metric('Vendas brutas',s.gross,'Receita por emissão de NF · Bling','chart')}${metric('Vendas líquidas',s.net,'Brutas menos taxas previstas','wallet')}${metric('Recebido e vinculado',s.received,'Liberações ligadas aos pedidos','check','green')}${metric('A receber',s.open,'Saldo líquido aberto, exceto trânsito','clock')}${metric('Em trânsito',s.transit,'Liberações ainda em processamento','arrow','purple')}${metric('Divergências',s.diff,'Diferença absoluta nos pedidos vinculados','alert',s.diff?'red':'')}${metric('Taxas previstas',s.fees,'Conforme registro de cada pedido','file')}${metric('Valor conciliado',s.reconciled,`${s.matched} de ${s.count} pedidos integralmente conciliados`,'shield','green')}</div>`}
function dashboard(){if(!db.orders.length&&!db.receipts.length)return `<div class="hero"><div><div class="eyebrow">Sua base está pronta</div><h2>Comece pelos seus relatórios.</h2><p>Nenhum dado fictício. Importe suas notas fiscais e liberações para calcular os indicadores da operação.</p><div class="row"><button class="primary" data-nav="imports">${icon('upload')} Importar primeiro relatório</button></div></div></div><div class="notice"><strong>Armazenamento neste navegador.</strong> Os registros não são sincronizados entre computadores. Exporte backups regularmente em Histórico e auditoria.</div>${metrics(stats())}`;let s=stats(),ratio=s.net?s.reconciled/s.net*100:0,unmatched=db.receipts.filter(r=>r.date.startsWith(month)&&!r.linkedOrder);return `<div class="hero"><div><div class="eyebrow">${icon('spark').replace('class="icon"','class="icon" style="vertical-align:middle;width:14px;height:14px"')} Inteligência que conecta os pontos</div><h2>Mais visibilidade. Melhores decisões.</h2><p>${s.matched} pedidos já estão conciliados. Há ${scoped().filter(o=>status(o)==='Divergência').length} divergências para revisar e ${unmatched.length} liberações aguardando vínculo. Tudo em um só lugar.</p><div class="row"><button data-nav="reconcile" class="primary small">Revisar conciliação ${icon('arrow')}</button><span class="caption">${money(s.reconciled)} conciliados</span></div></div><div class="row"><div class="ring" style="--progress:${ratio}%"><div><b>${pct(ratio)}</b><span>do valor líquido</span></div></div></div></div>${metrics(s)}<div class="grid charts"><div class="card"><div class="cardhead"><div><h2>O movimento da sua operação</h2><p class="caption">Vendas líquidas e recebimentos vinculados por data da NF</p></div><span class="badge">${scoped().length} pedidos</span></div>${chart()}<div class="legend"><span><i style="background:var(--accent)"></i>Vendas líquidas</span><span><i style="background:var(--green)"></i>Recebido vinculado</span></div></div><div class="card"><div class="cardhead"><h2>Mapa da conciliação</h2>${icon('link')}</div>${['Conciliado','A receber','Em trânsito','Divergência'].map((st,i)=>{let n=scoped().filter(o=>status(o)===st).length;return `<div class="progressrow"><div class="row"><span>${badge(st)}</span><span>${n} pedidos</span></div><div class="bar"><i style="width:${s.count?n/s.count*100:0}%;background:${['var(--green)','var(--gold)','var(--accent)','var(--red)'][i]}"></i></div></div>`}).join('')}<div class="listline"><span>A conciliar · liberações sem vínculo</span><strong class="gold">${money(unmatched.reduce((a,r)=>a+r.amount,0))}</strong></div><p class="caption">Sem vínculo não significa inadimplência ou perda.</p></div></div><div class="cardhead"><h2>Todo o ecossistema. Uma única visão.</h2><span class="caption">Importação manual · sem conexão com APIs</span></div><div class="grid platformgrid">${Object.keys(platforms).map(p=>{let ps=stats(p==='Bling'?scoped():p==='Mercado Pago'?scoped().filter(o=>o.platform==='Mercado Livre'):scoped().filter(o=>o.platform===p));return `<button class="card platform" data-nav="${p}"><div class="row">${logo(p)}<span style="font-size:12px">${p}</span></div><b>${money(p==='Mercado Pago'?db.receipts.filter(r=>r.account===p&&r.date.startsWith(month)).reduce((a,r)=>a+r.amount,0):ps.gross)}</b><span class="caption">${p==='Mercado Pago'?'Liberações no período':p==='Bling'?'Receita fiscal consolidada':'Vendas brutas'} ${icon('arrow').replace('class="icon"','class="icon" style="width:12px;height:12px;float:right"')}</span><div class="bar"><i style="width:${ps.net?ps.reconciled/ps.net*100:0}%;background:${platforms[p].color}"></i></div></button>`}).join('')}</div><div class="tablebox"><div class="tabletop"><h2>O que merece sua atenção</h2><button class="quiet small" data-nav="pending">Ver todas as pendências ${icon('arrow')}</button></div>${orderTable(scoped().filter(o=>status(o)!=='Conciliado').slice(0,5))}</div>`}
function chart(){const rows=scoped(),values=Array.from({length:7},(_,i)=>{let group=rows.filter(o=>[4,9,13,18,22,27,31].findIndex(d=>Number(o.date.slice(-2))<=d)===i);return [group.reduce((a,o)=>a+net(o),0),group.reduce((a,o)=>a+paid(o),0)]}),max=Math.max(1,...values.flat()),line=k=>values.map((v,i)=>`${i?'L':'M'}${45+i*83},${155-v[k]/max*125}`).join(' ');return `<svg class="chart" viewBox="0 0 570 190" role="img" aria-label="Gráfico por faixas de dias da competência"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop style="stop-color:var(--accent)" stop-opacity=".24"/><stop offset="1" style="stop-color:var(--accent)" stop-opacity="0"/></linearGradient></defs>${[0,1,2,3].map(i=>`<path d="M40 ${30+i*42}H550" stroke="var(--line)" stroke-dasharray="3 5"/><text x="0" y="${34+i*42}">${Math.round(max*(1-i/3)/1000)}k</text>`).join('')}<path d="${line(0)} L543 160 L45 160Z" fill="url(#fill)"/><path d="${line(0)}" fill="none" stroke="var(--accent)" stroke-width="2.5"/><path d="${line(1)}" fill="none" stroke="var(--green)" stroke-width="2"/>${values.map((v,i)=>`<circle cx="${45+i*83}" cy="${155-v[0]/max*125}" r="3" fill="var(--accent)"/><text x="${35+i*83}" y="181">${['01–04','05–09','10–13','14–18','19–22','23–27','28–31'][i]}</text>`).join('')}</svg>`}
function filters(){return `<div class="filters"><input type="search" id="search" placeholder="Buscar pedido ou nota fiscal…" value="${esc(filter)}" aria-label="Buscar pedido"><select id="platformFilter" aria-label="Filtrar plataforma"><option value="">Todas as plataformas</option>${['Mercado Livre','Shopee','Magalu'].map(p=>`<option ${p===platformFilter?'selected':''}>${p}</option>`).join('')}</select><select id="statusFilter" aria-label="Filtrar status"><option value="">Todos os status</option>${Object.keys(badges).filter(s=>s!=='A conciliar').map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select><button data-action="export-orders">${icon('download')} Exportar</button></div>`}
function filtered(rows){return rows.filter(o=>(!filter||`${o.id} ${o.nf}`.toLowerCase().includes(filter.toLowerCase()))&&(!platformFilter||o.platform===platformFilter)&&(!statusFilter||status(o)===statusFilter))}
function orderTable(rows){if(!rows.length)return '<div class="empty">Nenhum pedido encontrado para estes filtros.</div>';return `<div class="tablewrap"><table><thead><tr><th>Pedido / NF</th><th>Plataforma</th><th>Emissão</th><th class="num">Bruto</th><th class="num">Líquido</th><th class="num">Recebido</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(o=>`<tr><td><strong>${esc(o.id)}</strong><br><span class="caption">${esc(o.nf)} · ${esc(o.source)}</span></td><td><div class="row">${logo(o.platform)}${o.platform}</div></td><td>${o.date.split('-').reverse().join('/')}</td><td class="num">${money(o.gross)}</td><td class="num">${money(net(o))}</td><td class="num">${money(paid(o))}</td><td>${badge(status(o))}</td><td><button class="quiet small" data-order="${esc(o.id)}" aria-label="Abrir pedido ${esc(o.id)}">${icon('arrow')}</button></td></tr>`).join('')}</tbody></table></div>`}
function central(){return `<div class="notice"><strong>Conciliação com confirmação humana.</strong> O motor procura liberações por pedido, plataforma, valor e proximidade de data. Sugestões não alteram saldos até você confirmar um vínculo. ${db.closures[month]?'<strong>Competência fechada: alterações bloqueadas.</strong>':''}</div>${filters()}<div class="tablebox"><div class="tabletop"><h2>Pedidos da competência</h2><button class="primary small" data-action="matching">${icon('spark')} Buscar correspondências</button></div><div id="orderResults">${orderTable(filtered(scoped()))}</div></div>${unlinkedView()}`}
function candidates(o){return db.receipts.filter(r=>!r.linkedOrder&&r.platform===o.platform&&!db.closures[r.date.slice(0,7)]).map(r=>{let exact=r.orderId===o.id,delta=round(Math.abs(r.amount-Math.max(0,net(o)-paid(o)))),days=Math.abs(new Date(r.date)-new Date(o.date))/86400000,score=(exact?60:0)+(delta<.01?30:delta<=30?10:0)+(days<=7?10:days<=31?5:0);return {r,score,exact,delta,days}}).filter(c=>c.exact||c.delta<.01&&c.days<=7).sort((a,b)=>b.score-a.score)}
function unlinkedView(){const rs=db.receipts.filter(r=>r.date.startsWith(month)&&!r.linkedOrder);return `<div class="tablebox" style="margin-top:22px"><div class="tabletop"><div><h2>Liberações a conciliar</h2><p class="caption">Dinheiro reportado sem vínculo com um pedido · não compõe recebido vinculado</p></div><span class="badge warn">${rs.length} liberações</span></div>${rs.length?`<div class="tablewrap"><table><thead><tr><th>Liberação</th><th>Pedido informado</th><th>Conta</th><th>Data</th><th class="num">Valor</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.orderId||'Não informado')}</td><td>${esc(r.account)}</td><td>${r.date}</td><td class="num">${money(r.amount)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Todas as liberações do período estão vinculadas.</div>'}</div>`}
function modal(title,body){focusBefore=document.activeElement;$('#overlay').innerHTML=`<div class="modalback"><section class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="modalhead"><h2>${esc(title)}</h2><button data-action="close" class="quiet small" aria-label="Fechar">${icon('close')}</button></div>${body}</section></div>`;$('#overlay button')?.focus()}
function closeModal(){$('#overlay').innerHTML='';focusBefore?.focus()}
function detail(id){const o=db.orders.find(o=>o.id===id);if(!o)return;const cs=candidates(o),rs=db.receipts.filter(r=>r.linkedOrder===id),locked=!!db.closures[o.date.slice(0,7)];modal(`Pedido ${o.id}`,`<div class="row wrap" style="margin-bottom:20px">${logo(o.platform)}<strong>${o.platform}</strong>${badge(status(o))}<span class="caption">${esc(o.nf)} · ${o.date} · ${esc(o.source)}</span></div><div class="grid three"><div class="detailmetric"><span class="caption">Valor bruto</span><strong>${money(o.gross)}</strong></div><div class="detailmetric"><span class="caption">Taxas previstas</span><strong>${money(o.fee)}</strong></div><div class="detailmetric"><span class="caption">Líquido esperado</span><strong>${money(net(o))}</strong></div></div><div class="listline"><span>Recebido vinculado</span><strong class="green">${money(paid(o))}</strong></div><div class="listline"><span>Saldo líquido em aberto</span><strong>${money(Math.max(0,net(o)-paid(o)))}</strong></div><div class="listline"><span>Previsão de liberação</span><strong>${o.due}</strong></div>${o.external?.repasse_previsto!=null?`<div class="listline"><span>Venda na plataforma · tarifas e frete</span><strong>${money(o.external.venda_plataforma)} · ${money(o.external.tarifas_plataforma)}</strong></div><div class="listline"><span>Repasse previsto pela plataforma</span><strong>${money(o.external.repasse_previsto)}</strong></div>${Math.abs(o.external.diferenca_nf||0)>=0.01?`<div class="listline"><span>Diferença NF × venda na plataforma<br><span class="caption">Frete cobrado do cliente, juros ou acréscimos na NF. Não é repassado pela plataforma.</span></span><strong class="gold">${money(o.external.diferenca_nf)}</strong></div>`:''}`:''}<h3 style="margin-top:22px">Liberações vinculadas</h3>${rs.length?rs.map(r=>`<div class="listline"><span>${esc(r.id)}<br><span class="caption">${r.date} · ${esc(r.account)}</span></span><div>${money(r.amount)} <button class="quiet small" data-unlink="${esc(r.id)}" ${locked||db.closures[r.date.slice(0,7)]?'disabled':''}>Desvincular</button></div></div>`).join(''):'<p class="caption">Nenhuma liberação vinculada. Isso não caracteriza perda ou inadimplência.</p>'}<h3 style="margin-top:22px">Correspondências sugeridas</h3>${locked?'<p class="caption">Competência fechada. Reabra para alterar vínculos.</p>':cs.length?cs.slice(0,5).map(c=>`<div class="suggestion"><div class="row wrap"><strong>${esc(c.r.id)}</strong><span class="badge info">${c.score}/100 · pontuação por regras</span></div><p>${c.exact?'Pedido idêntico':'Pedido não identificado'} · diferença ${money(c.delta)} · ${c.days} dias de distância · ${money(c.r.amount)}</p><button class="primary small" data-link="${esc(c.r.id)}" data-target="${esc(id)}">Revisar vínculo ${icon('arrow')}</button></div>`).join(''):'<p class="caption">Nenhuma correspondência encontrada. Importe as liberações ou revise os identificadores.</p>'}<label for="note">Anotação da investigação</label><textarea id="note" ${locked?'disabled':''}>${esc(o.note)}</textarea><div class="modalfoot"><button data-investigate="${esc(id)}">${icon('spark')} Investigar</button><button data-save-note="${esc(id)}" class="primary" ${locked?'disabled':''}>Salvar anotação</button></div>`)}
function linkReview(rid,oid){const r=db.receipts.find(r=>r.id===rid),o=db.orders.find(o=>o.id===oid);modal('Confirmar vínculo',`<div class="notice">Esta ação associa uma liberação ao pedido e atualiza recebido, saldo e conciliação. Uma diferença de valor permanece como divergência.</div><div class="listline"><span>Pedido</span><strong>${esc(oid)}</strong></div><div class="listline"><span>Liberação</span><strong>${esc(rid)}</strong></div><div class="listline"><span>Valor da liberação</span><strong>${money(r.amount)}</strong></div><div class="listline"><span>Saldo atual do pedido</span><strong>${money(net(o)-paid(o))}</strong></div><div class="modalfoot"><button data-order="${esc(oid)}">Voltar</button><button class="primary" data-confirm-link="${esc(rid)}" data-target="${esc(oid)}">${icon('check')} Confirmar vínculo</button></div>`)}
function matching(){let rows=scoped().filter(o=>status(o)!=='Conciliado'),found=rows.map(o=>({o,c:candidates(o)})).filter(x=>x.c.length);audit('Matching executado',`${month}: ${found.length} pedidos com candidatos. Nenhum vínculo automático.`);modal('Correspondências encontradas',`<div class="notice">${found.length} pedidos possuem candidatos. A pontuação é uma regra de comparação, não uma probabilidade estatística. ${db.closures[month]?'A competência está fechada.':''}</div>${found.map(({o,c})=>`<div class="listline"><div><strong>${esc(o.id)}</strong><br><span class="caption">${c.length} candidato(s) · melhor pontuação ${c[0].score}/100</span></div><button data-order="${esc(o.id)}">Revisar ${icon('arrow')}</button></div>`).join('')||'<div class="empty">Nenhum candidato disponível. Importe um relatório de liberações.</div>'}`)}
function investigation(o){let s=status(o),p=paid(o),cs=candidates(o);return s==='Divergência'?`O líquido previsto é ${money(net(o))}, enquanto as liberações vinculadas somam ${money(p)}. A diferença é ${money(Math.abs(net(o)-p))}. Hipóteses a verificar: ajuste de tarifa, retenção ou liberação parcial. O relatório não comprova a causa; compare o extrato detalhado com as taxas do pedido.`:cs.length?`Encontrada(s) ${cs.length} liberação(ões) candidata(s). A melhor combinação tem ${cs[0].exact?'identificador de pedido idêntico':'valor compatível'}, diferença de ${money(cs[0].delta)} e distância de ${cs[0].days} dias. Revise a origem antes de confirmar o vínculo.`:s==='Em trânsito'?`Pedido sinalizado como em processamento. Não há liberação vinculada. Confira a previsão ${o.due} e o extrato da plataforma. Trânsito não é tratado como inadimplência.`:s==='Conciliado'?`As liberações vinculadas totalizam ${money(p)} e correspondem ao líquido previsto. Não há diferença aritmética neste pedido.`:`Não foi encontrada liberação compatível entre os registros disponíveis. Importe o extrato do período seguinte ou procure pelo identificador ${o.id}. Ausência de vínculo não comprova inadimplência ou perda.`}
function investigate(id){const o=db.orders.find(o=>o.id===id);audit('Investigação por regras',`Pedido ${id}: análise determinística de dados locais.`);modal('Investigação · '+id,`<div class="notice"><strong>Análise por regras locais.</strong> Não há modelo de IA conectado. Hipóteses são sugestões de investigação e exigem revisão.</div><div class="card"><div class="eyebrow">Evidências e próximos passos</div><p style="color:var(--text);line-height:1.9">${esc(investigation(o))}</p></div><div class="listline"><span>Fontes utilizadas</span><span>${esc(o.nf)}, pedido e liberações importadas</span></div><div class="modalfoot"><button data-order="${esc(id)}" class="primary">Abrir pedido ${icon('arrow')}</button></div>`)}
function aiView(){let rows=scoped().filter(o=>status(o)!=='Conciliado');return `<div class="notice"><strong>Investigação de divergências.</strong> Explicações geradas a partir dos valores, identificadores e datas dos seus relatórios. Não há modelo externo conectado; nenhuma sugestão altera vínculos automaticamente.</div><div class="grid two">${rows.map(o=>`<div class="card"><div class="cardhead"><div class="row">${logo(o.platform)}<h3>${esc(o.id)}</h3></div>${badge(status(o))}</div><p style="font-size:12px;min-height:90px">${esc(investigation(o))}</p><div class="row" style="margin-top:20px"><button class="small primary" data-investigate="${esc(o.id)}">${icon('spark')} Investigar</button><button class="small quiet" data-order="${esc(o.id)}">Ver pedido</button></div></div>`).join('')||'<div class="empty">Nenhuma pendência nesta competência.</div>'}</div>`}
function pendingView(){return `<div class="notice"><strong>A receber ≠ a conciliar.</strong> A receber é o saldo líquido aberto de um pedido. A conciliar são liberações disponíveis sem vínculo. As duas visões precisam ser revisadas antes do fechamento.</div>${filters()}<div class="tablebox"><div id="orderResults">${orderTable(filtered(scoped().filter(o=>status(o)!=='Conciliado')))}</div></div>${unlinkedView()}`}
function platformView(p){let rows=p==='Bling'?scoped():scoped().filter(o=>o.platform===(p==='Mercado Pago'?'Mercado Livre':p));return `<div class="card" style="margin-bottom:22px"><div class="cardhead"><div class="row">${logo(p)}<div><h2>${p}</h2><p class="caption">${platforms[p].role}</p></div></div><span class="badge warn">Conexão via importação manual</span></div><p>${p==='Bling'?'Origem do reconhecimento de receita: emissão da nota fiscal. A visão consolidada evita somar o ERP novamente às vendas dos marketplaces.':p==='Mercado Pago'?'Visão dos pedidos Mercado Livre e suas liberações. Mercado Pago é a conta de liquidação; seus valores não são somados como novas vendas.':'Acompanhe vendas, taxas, repasses e pendências desta plataforma.'}</p></div>${metrics(stats(rows))}<div class="tablebox"><div class="tabletop"><h2>${p==='Bling'?'Notas fiscais e pedidos':'Pedidos e liberações'}</h2><button class="small" data-nav="imports">${icon('upload')} Importar relatório</button></div>${orderTable(rows)}</div>`}
function importsView(){return `<div class="grid two"><div class="card"><div class="eyebrow">01 / Prepare seu relatório</div><h2>Importe pedidos ou liberações</h2><p>CSV padronizado, UTF-8, separado por ponto e vírgula ou vírgula. Até 5 MB e 10.000 linhas.</p><label for="importType">Tipo de relatório</label><select id="importType"><option value="orders">Pedidos / notas fiscais do Bling</option><option value="receipts">Liberações / extrato das plataformas</option></select><label class="dropzone" for="csvFile">${icon('upload')}<h3>Selecione seu arquivo CSV</h3><p class="caption">Prévia e validação antes de importar</p><input type="file" accept=".csv,text/csv" id="csvFile" style="margin-top:18px;width:100%"></label><button data-action="template">${icon('download')} Baixar modelo do tipo selecionado</button><div id="importPreview"></div></div><div class="stack"><div class="card"><div class="eyebrow">02 / Revise antes de confirmar</div><h2>Dados consistentes desde a origem</h2><div class="listline"><span>Duplicados</span><span>Bloqueados pelo identificador</span></div><div class="listline"><span>Datas</span><span>Formato AAAA-MM-DD</span></div><div class="listline"><span>Valores</span><span>1234.56 ou 1234,56</span></div><div class="listline"><span>Competência fechada</span><span>Importação bloqueada</span></div><p class="statnote">Pedidos: id, plataforma, data, bruto, taxa, nf, vencimento. Liberações: id, pedido, plataforma, conta, data, valor. Plataformas: Mercado Livre, Shopee ou Magalu. Conta também aceita Mercado Pago. Não importe arquivos nativos sem adaptar as colunas ao modelo.</p></div><div class="card"><h2>Fontes do ecossistema</h2>${Object.keys(platforms).map(p=>`<div class="integration"><div class="row">${logo(p)}${p}</div><span class="caption">CSV manual</span></div>`).join('')}</div></div></div><div class="tablebox" style="margin-top:22px"><div class="tabletop"><h2>Histórico de importações</h2></div>${db.imports.length?`<div class="tablewrap"><table><thead><tr><th>Arquivo</th><th>Tipo</th><th>Linhas</th><th>Importado em</th></tr></thead><tbody>${db.imports.map(i=>`<tr><td>${esc(i.file)}</td><td>${i.type==='orders'?'Pedidos':'Liberações'}</td><td>${i.count}</td><td>${new Date(i.time).toLocaleString('pt-BR')}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhum arquivo importado. Os dados iniciais são demonstrativos.</div>'}</div>`}
function parseCSV(text){text=text.replace(/^\uFEFF/,'');let sep=text.split(/\r?\n/)[0].includes(';')?';':',',rows=[],row=[],field='',quoted=false;for(let i=0;i<text.length;i++){let c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===sep&&!quoted){row.push(field.trim());field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field.trim());if(row.some(Boolean))rows.push(row);row=[];field=''}else field+=c}if(quoted)throw Error('Aspas não fechadas no CSV.');row.push(field.trim());if(row.some(Boolean))rows.push(row);return rows}
// Colunas opcionais de pedidos: cliente, documento, UF e um produto por pedido.
function orderExtras(r,gross){const out={},uf=String(r.uf||'').trim().toUpperCase();if(/^[A-Z]{2}$/.test(uf))out.state=uf;if(r.cliente||r.documento)out.customer={id:'',name:String(r.cliente||'').trim(),doc:String(r.documento||'').replace(/[^0-9]/g,''),state:out.state||''};if(r.produto||r.sku){const qty=Number(String(r.quantidade||'1').replace(',','.'))||1;out.items=[{sku:String(r.sku||'').trim(),title:String(r.produto||r.sku).trim(),qty,price:Number.isFinite(gross)?round(gross/qty):0}]}return out}
function validDate(s){return /^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s}
function decimal(s){if(!/^(?:\d+(?:[.,]\d{1,2})?|\d{1,3}(?:\.\d{3})+,\d{1,2})$/.test(s))return NaN;return Number(s.includes(',')?s.replace(/\./g,'').replace(',','.'):s)}
async function previewFile(file){if(!file)return;pendingImport=null;try{if(file.size>5*1024*1024)throw Error('Arquivo acima de 5 MB.');let type=$('#importType').value,rows=parseCSV(await file.text()),headers=rows.shift()?.map(h=>h.toLowerCase())||[],required=type==='orders'?['id','plataforma','data','bruto','taxa','nf','vencimento']:['id','pedido','plataforma','conta','data','valor'];if(required.some(h=>!headers.includes(h)))throw Error('Colunas obrigatórias: '+required.join(', '));if(new Set(headers).size!==headers.length)throw Error('Existem colunas repetidas.');if(!rows.length||rows.length>10000)throw Error('Informe entre 1 e 10.000 linhas.');let errors=[],seen=new Set(db[type].map(x=>x.id)),parsed=[];rows.forEach((row,i)=>{let r=Object.fromEntries(headers.map((h,j)=>[h,row[j]||''])),problems=[];if(row.length!==headers.length)problems.push('número de colunas inválido');if(!r.id||r.id.length>100)problems.push('ID obrigatório com até 100 caracteres');if(seen.has(r.id))problems.push('identificador duplicado');seen.add(r.id);if(!['Mercado Livre','Shopee','Magalu'].includes(r.plataforma))problems.push('plataforma inválida');if(!validDate(r.data))problems.push('data inválida');if(db.closures[r.data.slice(0,7)])problems.push('competência fechada');let item;if(type==='orders'){let gross=decimal(r.bruto),fee=decimal(r.taxa);if(!Number.isFinite(gross)||gross<=0||!Number.isFinite(fee)||fee<0||fee>gross)problems.push('bruto/taxa inválidos');if(!r.nf||!validDate(r.vencimento))problems.push('NF ou vencimento inválido');item={id:r.id,platform:r.plataforma,date:r.data,gross,fee,nf:r.nf,due:r.vencimento,transit:false,note:'',source:'Importado',...orderExtras(r,gross)}}else{let amount=decimal(r.valor);if(!Number.isFinite(amount)||amount<=0)problems.push('valor deve ser positivo');if(!Object.keys(platforms).filter(p=>p!=='Bling').includes(r.conta))problems.push('conta inválida');item={id:r.id,orderId:r.pedido,platform:r.plataforma,account:r.conta,date:r.data,amount,linkedOrder:null,source:'Importado'}}if(problems.length)errors.push(`Linha ${i+2}: ${problems.join('; ')}`);parsed.push(item)});pendingImport=errors.length?null:{type,items:parsed,file:file.name};$('#importPreview').innerHTML=`<div class="notice" style="margin-top:20px"><strong>${rows.length} linhas lidas · ${errors.length} linhas com erro</strong><p>${errors.length?errors.slice(0,8).map(esc).join('<br>'):'Validação concluída. Nenhum dado foi gravado ainda.'}</p></div>${!errors.length?`<div class="tablewrap"><table><thead><tr><th>ID</th><th>Plataforma</th><th>Data</th><th>Valor</th></tr></thead><tbody>${parsed.slice(0,5).map(r=>`<tr><td>${esc(r.id)}</td><td>${esc(r.platform)}</td><td>${r.date}</td><td>${money(r.gross??r.amount)}</td></tr>`).join('')}</tbody></table></div><p class="caption">Prévia das primeiras ${Math.min(5,parsed.length)} linhas. Registros importados serão identificados como Importado.</p><button class="primary" style="margin-top:15px" data-action="confirm-import">Confirmar ${parsed.length} registros</button>`:''}`;audit('Arquivo validado',`${file.name}: ${rows.length} linhas, ${errors.length} erros.`)}catch(e){$('#importPreview').innerHTML=`<div class="notice red" style="margin-top:15px">${esc(e.message)}</div>`}}
function closingView(){let s=stats(),open=scoped().filter(o=>status(o)!=='Conciliado').length,unlinked=db.receipts.filter(r=>r.date.startsWith(month)&&!r.linkedOrder).length,c=db.closures[month];return `<div class="notice"><strong>Competência por emissão de NF.</strong> Liberações baixam o saldo do pedido vinculado. O fechamento guarda um retrato local dos indicadores e bloqueia alterações nos pedidos e liberações da competência.</div><div class="grid two"><div class="card"><div class="cardhead"><h2>Checklist do fechamento</h2>${badge(c?'Fechado':'Em revisão')}</div><div class="listline"><span>Pedidos com nota fiscal</span><strong>${scoped().filter(o=>o.nf).length} / ${s.count}</strong></div><div class="listline"><span>Pedidos integralmente conciliados</span><strong>${s.matched} / ${s.count}</strong></div><div class="listline"><span>Pedidos em aberto / divergentes</span><strong class="gold">${open}</strong></div><div class="listline"><span>Liberações sem vínculo no período</span><strong class="gold">${unlinked}</strong></div><div class="listline"><span>Valor conciliado</span><strong class="green">${money(s.reconciled)}</strong></div><div class="row" style="margin-top:20px"><button data-nav="pending">Revisar pendências</button><button class="primary" data-action="${c?'reopen':'close-month'}" ${!s.count&&!c?'disabled':''}>${icon('shield')}${c?'Reabrir competência':'Preparar fechamento'}</button></div></div><div class="card"><div class="eyebrow">Memória do fechamento</div><h2>${c?'Competência fechada':'O controle fica com você'}</h2>${c?`<p>Fechamento em ${new Date(c.time).toLocaleString('pt-BR')}.</p><div class="listline"><span>Conciliado no fechamento</span><strong>${money(c.stats.reconciled)}</strong></div><div class="listline"><span>Ressalvas registradas</span><strong>${c.open} pedidos / ${c.unlinked} liberações</strong></div><p>${esc(c.note)}</p><button style="margin-top:20px" data-action="export-close">${icon('download')} Exportar retrato do fechamento</button>`:'<p style="line-height:1.9;margin-top:16px">Revise as pendências antes de fechar. É possível fechar com ressalvas, desde que você registre uma justificativa e confirme a revisão. A reabertura também exige motivo e fica na auditoria.</p>'}</div></div>`}
function prepareClose(){let open=scoped().filter(o=>status(o)!=='Conciliado').length,unlinked=db.receipts.filter(r=>r.date.startsWith(month)&&!r.linkedOrder).length;modal('Fechar competência '+month,`<div class="notice">${open} pedidos ainda não estão conciliados e ${unlinked} liberações não têm vínculo. ${open+unlinked?'O fechamento será registrado com ressalvas.':'A revisão pode ser concluída.'}</div><label for="closeNote">${open+unlinked?'Justificativa das ressalvas (obrigatória)':'Observações'}</label><textarea id="closeNote" placeholder="Registre a revisão e o tratamento das pendências…"></textarea><label><input class="check" type="checkbox" id="closeReviewed"> Revisei os indicadores e reconheço as pendências acima.</label><div class="modalfoot"><button data-action="close">Cancelar</button><button data-action="confirm-close" class="primary">Confirmar fechamento</button></div>`)}
function reportsView(){let s=stats();return `<div class="notice"><strong>Relatórios de apoio à contabilidade.</strong> Demonstrativos operacionais baseados nas NFs, taxas previstas e liberações vinculadas. Não substituem escrituração fiscal. Arquivos exportados identificam a origem demonstrativa ou importada dos registros.</div><div class="grid three">${[['orders','Pedidos detalhados','NF, plataforma, bruto, taxas, líquido, recebido e saldo.'],['summary','Resumo da competência','Indicadores por marketplace sem duplicar ERP e conta de pagamento.'],['receipts','Liberações e vínculos','Extrato de liberações por data, conta e pedido vinculado.']].map(([id,t,d])=>`<div class="card"><span class="purple">${icon('file')}</span><h2 style="margin:15px 0 8px">${t}</h2><p style="font-size:12px;min-height:55px">${d}</p><button data-export="${id}" style="margin-top:20px">${icon('download')} Exportar CSV</button></div>`).join('')}</div><div class="card" style="margin-top:22px"><div class="cardhead"><h2>Prévia · ${month}</h2><button data-action="print">${icon('file')} Imprimir / PDF</button></div>${[['Receita bruta por NF',s.gross],['Taxas previstas',s.fees],['Líquido esperado',s.net],['Recebido vinculado',s.received],['Saldo a receber (exceto trânsito)',s.open],['Em trânsito',s.transit],['Conciliado',s.reconciled]].map(([l,v])=>`<div class="listline"><span>${l}</span><strong>${money(v)}</strong></div>`).join('')}</div>`}
function historyView(){return `<div class="notice">Histórico local deste navegador. Registra importações, confirmações, desvínculos, investigações e fechamentos. Esta versão não oferece trilha inviolável nem autenticação de usuários.</div><div class="card"><div class="cardhead"><h2>Trilha de atividades</h2><div class="row"><button class="small" data-action="export-audit">${icon('download')} Exportar auditoria</button><button class="small" data-action="backup">Backup JSON</button></div></div><div class="timeline">${db.audit.map(a=>`<div class="event"><strong>${esc(a.action)}</strong><p>${esc(a.detail)}</p><span class="caption">${new Date(a.time).toLocaleString('pt-BR')} · Operador local</span></div>`).join('')}</div></div>`}
function download(filename,data,type='text/csv;charset=utf-8'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000)}
function csv(rows){return '\uFEFF'+rows.map(r=>r.map(v=>{let s=String(v??'');if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}).join(';')).join('\r\n')}
function exportData(type){let rows;if(type==='orders'){let os=page==='pending'?scoped().filter(o=>status(o)!=='Conciliado'):scoped();rows=[['pedido','nf','plataforma','emissao','bruto','taxas_previstas','liquido','recebido_vinculado','saldo_aberto','status','origem','nota'],...filtered(os).map(o=>[o.id,o.nf,o.platform,o.date,o.gross,o.fee,net(o),paid(o),Math.max(0,round(net(o)-paid(o))),status(o),o.source,o.note])]}else if(type==='receipts')rows=[['liberacao','pedido_informado','pedido_vinculado','plataforma','conta','data','valor','origem'],...db.receipts.filter(r=>r.date.startsWith(month)).map(r=>[r.id,r.orderId,r.linkedOrder||'',r.platform,r.account,r.date,r.amount,r.source])];else rows=[['competencia','plataforma','bruto','taxas_previstas','liquido','recebido_vinculado','a_receber','em_transito','divergencia_absoluta','conciliado','ambiente'],...['Mercado Livre','Shopee','Magalu'].map(p=>{let s=stats(scoped().filter(o=>o.platform===p));return [month,p,s.gross,s.fees,s.net,s.received,s.open,s.transit,s.diff,s.reconciled,'Dados importados / armazenamento local']})];download(`Jarvis_${type}_${month}.csv`,csv(rows));audit('Relatório exportado',`${type} · competência ${month}`);toast('Relatório CSV gerado.')}
function bindFilters(){if($('#search'))$('#search').oninput=e=>{filter=e.target.value;refreshRows()};if($('#platformFilter'))$('#platformFilter').onchange=e=>{platformFilter=e.target.value;refreshRows()};if($('#statusFilter'))$('#statusFilter').onchange=e=>{statusFilter=e.target.value;refreshRows()};if($('#csvFile'))$('#csvFile').onchange=e=>previewFile(e.target.files[0]);if($('#importType'))$('#importType').onchange=()=>{pendingImport=null;$('#csvFile').value='';$('#importPreview').innerHTML=''}}
function refreshRows(){let rows=page==='pending'?scoped().filter(o=>status(o)!=='Conciliado'):scoped();$('#orderResults').innerHTML=orderTable(filtered(rows))}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b||b.disabled)return;let d=b.dataset;if(d.mod){const m=MODULOS.find(m=>m.id===d.mod);moduloAtual=m.id;try{localStorage.setItem('ecombalance_mod',m.id)}catch{}navigate(m.itens[0][1][0]);return}if(d.nav){navigate(d.nav);return}if(d.order){detail(d.order);return}if(d.investigate){investigate(d.investigate);return}if(d.link){linkReview(d.link,d.target);return}if(d.confirmLink){let r=db.receipts.find(r=>r.id===d.confirmLink),o=db.orders.find(o=>o.id===d.target);if(r.linkedOrder||db.closures[o.date.slice(0,7)]||db.closures[r.date.slice(0,7)])return toast('Vínculo indisponível ou competência fechada.');r.linkedOrder=o.id;audit('Vínculo confirmado',`${r.id} → ${o.id} · ${money(r.amount)}`);render();detail(o.id);toast('Vínculo confirmado e saldos atualizados.');return}if(d.unlink){let r=db.receipts.find(r=>r.id===d.unlink),o=db.orders.find(o=>o.id===r.linkedOrder);modal('Desvincular liberação',`<p>Remover o vínculo de ${esc(r.id)} com ${esc(o.id)}? O valor voltará a ficar a conciliar.</p><div class="modalfoot"><button data-order="${esc(o.id)}">Cancelar</button><button class="primary" data-confirm-unlink="${esc(r.id)}">Confirmar desvínculo</button></div>`);return}if(d.confirmUnlink){let r=db.receipts.find(r=>r.id===d.confirmUnlink),o=db.orders.find(o=>o.id===r.linkedOrder);if(!o||db.closures[o.date.slice(0,7)]||db.closures[r.date.slice(0,7)])return toast('Competência fechada.');r.linkedOrder=null;audit('Liberação desvinculada',`${r.id} do pedido ${o.id}`);render();detail(o.id);return}if(d.saveNote){let o=db.orders.find(o=>o.id===d.saveNote);if(db.closures[o.date.slice(0,7)])return;o.note=$('#note').value;audit('Anotação salva',`${o.id}: ${o.note}`);toast('Anotação salva.');return}if(d.export){exportData(d.export);return}switch(d.action){case'menu':document.body.classList.toggle('menu');break;case'theme':db.theme=db.theme==='light'?'dark':'light';document.body.classList.toggle('light',db.theme==='light');if(!loadFailure)save();render();if(loadFailure)toast('Não foi possível ler os dados anteriores. Não importe antes de verificar o armazenamento do navegador.');break;case'close':closeModal();break;case'matching':matching();break;case'export-orders':exportData('orders');break;case'template':{let t=$('#importType').value,rows=t==='orders'?[['id','plataforma','data','bruto','taxa','nf','vencimento','cliente','documento','uf','produto','sku','quantidade']]:[['id','pedido','plataforma','conta','data','valor']];download(`modelo_${t}.csv`,csv(rows));toast('Modelo CSV vazio gerado.');break}case'confirm-import':{if(!pendingImport)return;let p=pendingImport;if(p.items.some(x=>db.closures[x.date.slice(0,7)]||db[p.type].some(y=>y.id===x.id)))return toast('A base mudou. Selecione o arquivo novamente.');db[p.type].push(...p.items);db.imports.unshift({file:p.file,type:p.type,count:p.items.length,time:new Date().toISOString()});audit('Importação confirmada',`${p.file}: ${p.items.length} ${p.type==='orders'?'pedidos':'liberações'}.`);pendingImport=null;render();toast('Importação concluída. Execute o matching para revisar vínculos.');break}case'close-month':prepareClose();break;case'confirm-close':{let open=scoped().filter(o=>status(o)!=='Conciliado').length,unlinked=db.receipts.filter(r=>r.date.startsWith(month)&&!r.linkedOrder).length,note=$('#closeNote').value.trim();if(!$('#closeReviewed').checked)return toast('Confirme que revisou os indicadores.');if(open+unlinked&&!note)return toast('Registre uma justificativa para as ressalvas.');db.closures[month]={time:new Date().toISOString(),stats:stats(),open,unlinked,note,orders:JSON.parse(JSON.stringify(scoped())),receipts:JSON.parse(JSON.stringify(db.receipts.filter(r=>r.date.startsWith(month)||scoped().some(o=>o.id===r.linkedOrder))))};audit('Competência fechada',`${month} · ${open} pedidos pendentes · ${unlinked} liberações sem vínculo · ${note}`);closeModal();render();toast('Fechamento registrado.');break}case'reopen':modal('Reabrir competência',`<p>O fechamento atual será removido e a competência voltará a permitir alterações. Exporte o retrato antes de prosseguir se precisar preservá-lo.</p><label for="reopenNote">Motivo obrigatório</label><textarea id="reopenNote"></textarea><div class="modalfoot"><button data-action="close">Cancelar</button><button class="primary" data-action="confirm-reopen">Confirmar reabertura</button></div>`);break;case'confirm-reopen':{let note=$('#reopenNote').value.trim();if(!note)return toast('Informe o motivo da reabertura.');delete db.closures[month];audit('Competência reaberta',`${month} · ${note}`);closeModal();render();break}case'export-close':download(`Jarvis_fechamento_${month}.json`,JSON.stringify({environment:'Dados importados / armazenamento local',competence:month,...db.closures[month]},null,2),'application/json');break;case'export-audit':download('Jarvis_auditoria.csv',csv([['data','acao','detalhe','operador'],...db.audit.map(a=>[a.time,a.action,a.detail,'Operador local'])]));break;case'backup':download('Jarvis_backup.json',JSON.stringify(db,null,2),'application/json');toast('Backup completo gerado.');break;case'print':window.print();break}});
document.addEventListener('keydown',e=>{if(!$('#overlay').children.length)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){let els=[...$('#overlay').querySelectorAll('button:not(:disabled),input:not(:disabled),textarea:not(:disabled),select:not(:disabled)')];if(e.shiftKey&&document.activeElement===els[0]){e.preventDefault();els.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===els.at(-1)){e.preventDefault();els[0].focus()}}});
if(!loadFailure)save();render();if(loadFailure)toast('Não foi possível ler os dados anteriores. Não importe antes de verificar o armazenamento do navegador.');
